python3 - <<'EOF'
import copy
from ocean_sonar import terrain
from ocean_sonar.terrain import dashboard, quality as q_orig, trend as t_orig

assert "dashboard" in terrain.__all__

layers = [
    (1.0, 3, 3, [(2, 10.0)] * 9),
    (2.0, 3, 3, [(2, 10.0)] * 9),
]
snap = copy.deepcopy(layers)

calls = []
def q_cap(ls, sl=5.0, rl=1.0):
    calls.append(("q", ls, sl, rl))
    return q_orig(ls, sl, rl)
def t_cap(ls, sl=5.0, rl=1.0):
    calls.append(("t", ls, sl, rl))
    return t_orig(ls, sl, rl)
terrain.quality = q_cap
terrain.trend = t_cap
D = dashboard(layers, 2.0, 3.0)
terrain.quality = q_orig
terrain.trend = t_orig

assert [c[0] for c in calls] == ["q", "t"]
assert calls[0][1] is layers and calls[1][1] is layers
assert calls[0][2:] == (2.0, 3.0) and calls[1][2:] == (2.0, 3.0)
Q, T = D["quality"], D["trend"]
assert list(D.keys()) == ["quality", "trend", "overall"]
assert D["quality"] is Q and D["trend"] is T
assert D["overall"] == "pass", D
assert layers == snap

layers2 = [
    (1.0, 3, 3, [(1, 0.0)] * 4 + [(1, 50.0)] + [(1, 0.0)] * 4),
    (2.0, 3, 3, [(1, 0.0)] * 4 + [(1, 50.0)] + [(1, 0.0)] * 4),
]
assert dashboard(layers2, slope_limit=5.0)["overall"] == "fail"

l1 = (1.0, 3, 3, [(1, 10.0)] * 9)
l2 = (2.0, 3, 3, [(1, 0.0)] * 4 + [(1, 50.0)] + [(1, 0.0)] * 4)
l3 = (3.0, 3, 3, [(1, 0.0)] * 4 + [(1, 50.0)] + [(1, 0.0)] * 4)
d3 = dashboard([l1, l2, l3], 5.0, 1000.0)
print("quality:", d3["quality"]["quality"], "trend:", d3["trend"]["overall"], "overall:", d3["overall"])
assert d3["overall"] == "fail"

# container/type errors
try:
    dashboard("x")
except TypeError as e:
    assert str(e) == "layers must be a list or tuple"
else:
    raise AssertionError

# empty -> ValueError
try:
    dashboard([])
except ValueError:
    pass
else:
    raise AssertionError

# r ordering
try:
    dashboard([(2.0, 3, 3, [(1, 1.0)] * 9), (1.0, 3, 3, [(1, 1.0)] * 9)])
except ValueError as e:
    assert str(e).startswith("layers[1]: "), e
else:
    raise AssertionError

# cell prefix + TypeError
try:
    dashboard([(1.0, 1, 1, [(True, 1.0)])])
except TypeError as e:
    assert str(e).startswith("layers[0].cells[0]: "), e
else:
    raise AssertionError

# layer container TypeError prefix
try:
    dashboard([42])
except TypeError as e:
    assert str(e).startswith("layers[0]: "), e
else:
    raise AssertionError

# nan mean -> ValueError cell prefix
import math
try:
    dashboard([(1.0, 1, 1, [(1, float("nan"))])])
except ValueError as e:
    assert str(e).startswith("layers[0].cells[0]: "), e
else:
    raise AssertionError

# thresholds
try:
    dashboard([(1.0, 1, 1, [(1, 1.0)])], slope_limit=True)
except TypeError as e:
    assert "slope_limit" in str(e)
else:
    raise AssertionError

try:
    dashboard([(1.0, 1, 1, [(1, 1.0)])], roughness_limit=0)
except ValueError as e:
    assert "roughness_limit" in str(e)
else:
    raise AssertionError

try:
    dashboard([(1.0, 1, 1, [(1, 1.0)])], slope_limit=float("inf"))
except ValueError:
    pass
else:
    raise AssertionError

# quality exception propagates; trend not called
calls2 = []
def q_boom(ls, sl=5.0, rl=1.0):
    calls2.append("q"); raise RuntimeError("boom")
def t_boom(ls, sl=5.0, rl=1.0):
    calls2.append("t"); return t_orig(ls, sl, rl)
terrain.quality = q_boom
terrain.trend = t_boom
try:
    dashboard([(1.0, 1, 1, [(1, 1.0)])])
except RuntimeError as e:
    assert str(e) == "boom"
else:
    raise AssertionError
assert calls2 == ["q"]
terrain.quality = q_orig
terrain.trend = t_orig

print("all checks passed")
EOF
